export class FeedbackAudio {
 constructor(orb){this.orb=orb;this.enabled=localStorage.getItem('argos-ui-sound')!=='off';this.context=null;this.audio=new Audio();this.audio.preload='auto';this.active=false;this.generation=0;this.bars=Array.from({length:13},()=>{const e=document.createElement('i');document.querySelector('#speech-wave').append(e);return e})}
 async unlock(){if(!this.context){this.context=new AudioContext();this.master=this.context.createGain();this.master.gain.value=this.enabled?.55:0;this.master.connect(this.context.destination);this.analyser=this.context.createAnalyser();this.analyser.fftSize=128;this.source=this.context.createMediaElementSource(this.audio);this.source.connect(this.analyser);this.analyser.connect(this.master);this.levels=new Uint8Array(this.analyser.frequencyBinCount);this.animate()}await this.context.resume()}
 toggle(){this.enabled=!this.enabled;localStorage.setItem('argos-ui-sound',this.enabled?'on':'off');if(this.master)this.master.gain.value=this.enabled?.55:0;return this.enabled}
 chime(kind='open'){if(!this.enabled||!this.context)return;const at=this.context.currentTime;const notes=kind==='done'?[740,1110,1480]:kind==='close'?[880,660]:[1320,1980];for(const [i,f] of notes.entries()){const o=this.context.createOscillator(),g=this.context.createGain();o.type='sine';o.frequency.value=f;o.connect(g);g.connect(this.master);g.gain.setValueAtTime(0,at+i*.045);g.gain.linearRampToValueAtTime(.055/(i+1),at+i*.045+.008);g.gain.exponentialRampToValueAtTime(.0001,at+i*.045+.48);o.start(at+i*.045);o.stop(at+i*.045+.5)}}
 async speak(file,text,caption){const generation=++this.generation;this.audio.pause();caption(text);if(!this.enabled||!this.context)return;this.audio.src=file;this.active=true;try{await this.audio.play();await new Promise(resolve=>{this.audio.onended=resolve;this.audio.onerror=resolve;setTimeout(resolve,15000)})}catch{}if(this.generation===generation)this.active=false}
 stop(){this.generation++;this.audio.pause();this.active=false}
 animate(){requestAnimationFrame(()=>this.animate());if(!this.context)return;this.analyser.getByteFrequencyData(this.levels);let sum=0;for(let i=0;i<this.levels.length;i++)sum+=this.levels[i];const energy=this.active?sum/this.levels.length/255:0;if(this.active)this.orb.setEnergy(energy);if(this.active)this.bars.forEach((e,i)=>e.style.height=(3+(this.active?this.levels[i*3]/255*16:0))+'px')}
}
